CREATE TABLE IF NOT EXISTS session_todos (session_id VARCHAR(36) PRIMARY KEY, id VARCHAR(36) NOT NULL, team_id VARCHAR(36) NOT NULL, reference text NOT NULL, refs text NOT NULL, status VARCHAR(16) NOT NULL, stall INT NOT NULL, last_done INT NULL, last_items INT NULL, last_notes INT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, CONSTRAINT session_todos_session FOREIGN KEY (session_id) REFERENCES cloud_sessions(id) ON DELETE CASCADE);
ALTER TABLE session_todos ADD CONSTRAINT session_todo_id UNIQUE (id);
CREATE TABLE IF NOT EXISTS session_todo_items (session_id VARCHAR(36), id VARCHAR(40), `position` INT NOT NULL, `name` VARCHAR(80) NOT NULL, description text NOT NULL, done_when MEDIUMTEXT NOT NULL, depends_on text NOT NULL, origin VARCHAR(16) NOT NULL, origin_reason text NULL, status VARCHAR(16) NOT NULL, proof text NULL, notes MEDIUMTEXT NOT NULL, drop_reason text NULL, drop_wait_id VARCHAR(36) NULL, CONSTRAINT pk_session_todo_items PRIMARY KEY (session_id, id), CONSTRAINT session_todo_items_todo FOREIGN KEY (session_id) REFERENCES session_todos(session_id) ON DELETE CASCADE);
CREATE INDEX session_todo_item_position ON session_todo_items (session_id, `position`);